import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-multitext-list',
  templateUrl: './multitext-list.component.html',
  styleUrls: ['./multitext-list.component.css']
})
